"""Generate cost_sensitive_results.md, sequential_rl_results.md, experimental_protocol.md, limitations.md and
final_research_report.md strictly from saved outputs in results/ (no metric value is typed by hand).
The reports written by other scripts (dataset_audit, supervised_results, distribution_shift_results,
safe_adaptation_results) are checked to exist. Hard-fails if a mandatory input is missing."""
import _bootstrap, json
import numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from src.common import ROOT, load_config, read_json

R = ROOT / "results"; REP = ROOT / "reports"; FIG = R / "figures"
cfg = load_config()

def need(p):
    p = ROOT / p
    if not p.exists(): raise SystemExit(f"mandatory input missing: {p}")
    return p
def f(x, n=3): return "n/a" if x is None or (isinstance(x, float) and np.isnan(x)) else f"{x:.{n}f}"
def md(df, cols, fmt=None):
    fmt = fmt or {}
    out = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    for _, r in df.iterrows(): out.append("| " + " | ".join(fmt[c](r[c]) if c in fmt else (f(r[c]) if isinstance(r[c], (float, np.floating)) else str(r[c])) for c in cols) + " |")
    return "\n".join(out)

def boot_ci(x, n=2000, seed=0):
    x = np.asarray(x, float); rng = np.random.default_rng(seed)
    m = np.array([x[rng.integers(0, len(x), len(x))].mean() for _ in range(n)]); return float(np.percentile(m, 2.5)), float(np.percentile(m, 97.5))

# ------------------------------------------------------------------ cost-sensitive (static)
def cost_report():
    S = pd.read_csv(need("results/cost_static_policies.csv")); info = read_json(need("results/rl_run_info.json"))
    L = ["# Cost-sensitive decision results (static policies)", "",
         f"_Generated by `scripts/make_reports.py` from `results/cost_static_policies.csv`. Status: **Executed and verified** for the data-driven part; the **cost matrix is an ASSUMPTION** (no operational cost data was supplied): FN (allowed phishing) = {info['costs']['fn']}, FP (blocked legitimate) = {info['costs']['fp']}, INSPECT = {info['costs']['inspect']} cost units; inspection capacity = {info['costs']['capacity_frac']:.0%} of arrivals._", "",
         "**Action semantics.** ALLOW = deliver; BLOCK = prevent access; INSPECT = quarantine and send to a human analyst (consumes capacity, costs the inspection price, analyst assumed perfect and instantaneous *in this static comparison*; delay/noise are handled only in the sequential environment).", "",
         "All policies are scored on the same registered-domain-disjoint test stream (random arrival order, fixed seed) with the same costs and capacity. Thresholds/bands/bandit statistics are fitted on the validation or *policy* partitions only. `capacity_violations` counts inspections requested beyond the capacity; policies that ignore capacity are shown with their violations rather than hidden. `bayes_batch_topK` needs the whole queue in advance (non-causal) and is an oracle-style reference, not an online policy.", ""]
    for cl, g in S.groupby("classifier", sort=False):
        g = g.copy(); g["rank"] = g.cost.rank(method="min").astype(int)
        L += [f"## Classifier: {cl}", "", f"_{g.tuning.iloc[0]}_", "", md(g.sort_values("cost"), ["policy", "cost_per_1k", "fn", "fp", "inspections", "capacity_K", "capacity_violations"], {"cost_per_1k": lambda x: f(x, 1), "fn": str, "fp": str, "inspections": str, "capacity_K": str, "capacity_violations": str}), ""]
    L += ["Reading guide: costs are only comparable within a classifier block (same probabilities, same stream). `bayes_expected_cost_unconstrained` is the cost-optimal rule under perfect calibration *if* capacity were unlimited; its capacity violations show why capacity-aware policies are needed. A policy is not claimed optimal: the Bayes rule is optimal only under calibrated probabilities and the stated cost matrix."]
    (REP / "cost_sensitive_results.md").write_text("\n".join(L) + "\n")

# ------------------------------------------------------------------ sequential RL
def rl_tables():
    E = pd.read_csv(need("results/rl_episode_results.csv")); info = read_json(need("results/rl_run_info.json"))
    E["is_rl"] = E.policy.str.startswith("RL_Q"); E["is_bandit"] = E.policy.str.startswith("bandit")
    rows, pair = [], []
    for (sc, mode), g in E.groupby(["scenario", "mode"], sort=False):
        # per-episode cost per policy (average over agent seeds for learners -> one value per episode, paired by episode id)
        pe = g.groupby(["policy", "episode"]).cost.mean().unstack(0)
        for pol in pe.columns:
            x = pe[pol].values; lo, hi = boot_ci(x)
            gg = g[g.policy == pol]
            seed_means = gg.groupby("seed").cost.mean()
            rows.append(dict(scenario=sc, mode=mode, policy=pol, n_episodes=len(x), cost=x.mean(), lo=lo, hi=hi, seeds=gg.seed.nunique(), seed_min=seed_means.min(), seed_max=seed_means.max(),
                             fn=gg.fn.mean(), fp=gg.fp.mean(), inspections=gg.inspections.mean(), violations=gg.violations.mean(), analyst_errors=gg.analyst_errors.mean()))
        base = [c for c in pe.columns if not c.startswith(("RL_Q", "bandit", "random"))]
        best_b = min(base, key=lambda c: pe[c].mean())
        for pol in [c for c in pe.columns if c.startswith(("RL_Q", "bandit"))]:
            d = (pe[pol] - pe[best_b]).values; lo, hi = boot_ci(d, seed=1)
            pair.append(dict(scenario=sc, mode=mode, learner=pol, best_nonlearning_baseline=best_b, mean_diff=d.mean(), lo=lo, hi=hi, learner_better=bool(hi < 0), learner_worse=bool(lo > 0)))
    return E, pd.DataFrame(rows), pd.DataFrame(pair), info

def rl_report():
    E, T, P, info = rl_tables()
    T.to_csv(R / "rl_summary_table.csv", index=False); P.to_csv(R / "rl_paired_vs_best_baseline.csv", index=False)
    full = "FAST (reduced budget; NOT the full experiment)" if info.get("fast") else "FULL"
    rl = info["rl"]
    L = ["# Sequential reinforcement-learning results (SIMULATED environment)", "",
         f"_Generated by `scripts/make_reports.py` from `results/rl_episode_results.csv`. Run mode: **{full}**. Status: **Simulated** — transitions, inspection capacity, delays, label noise and arrival regimes are modelling assumptions; only the URL labels and classifier probabilities come from real held-out data. These results say nothing about real SOC performance._", "",
         f"**Environment** (`src/rl/env.py`): episodes of T={info['T']} URL arrivals; per-episode inspection budget K={info['K']} (never replenished) so inspecting now removes the ability to inspect later; an inspected case is quarantined, its analyst label (flipped with probability `noise`) arrives after a random delay (mean `d`), accrues a hold cost per pending step, and mistakes are charged on resolution; pending cases are flushed at the end (no end-of-episode dodging). Agent-visible state: calibrated probability bin, remaining-budget-vs-time pace, arrival-risk EMA, confirmed-phishing-rate EMA, pending count. Hidden: true label, regime, future arrivals, delay/flip draws. Reward = −(cost incurred), derived from the same cost matrix as the static policies (fn={info['costs']['fn']}, fp={info['costs']['fp']}, inspect={info['costs']['inspect']}, hold=0.01/step; ASSUMED). Invalid INSPECT with an empty budget is overridden by a threshold decision and counted as a violation.", "",
         f"**Learners.** Tabular Q-learning with the Bellman update `Q(s,a) ← Q(s,a) + α(r + γ·max_a' Q(s',a') − Q(s,a))` (terminal states do not bootstrap; invalid actions masked), ε-greedy, γ={rl['gamma']}, α={rl['alpha']}, {rl['train_episodes']} training episodes per agent, agent seeds {rl['agent_seeds']}. `RL_Q(full)` uses the full discretised state; `RL_Q(budget_only)` uses probability bin + budget pace only; `bandit(full,g=0)` is the *same* learner with γ=0 (a contextual bandit on the same state), isolating the effect of sequential credit assignment. Training episodes (seeds 1000+e) and evaluation episodes (seeds 900000+i) are drawn from different classifier-output partitions (policy vs. test) and are disjoint. All policies are evaluated on the **identical** pre-drawn evaluation episodes (common random numbers): {rl['eval_episodes']} episodes per scenario.", "",
         "**Baselines (all observe the same tuple; all respect the same budget).** `fixed_0.5`; `val_tuned_threshold` (cost-optimal on validation); `bayes_unmasked`/`greedy_masked(bayes)` (inspect when the expected cost of the best terminal action exceeds the inspection price; inspection requests beyond budget fall back to a threshold decision); `uncertainty_band` (band tuned on training-environment episodes); `pacing_heuristic` and `pacing+prior_adapt` (hand-built capacity-aware pacing that spends the remaining budget at a uniform rate, the second also correcting for the running arrival-risk estimate); `random_valid`.", ""]
    cols = ["policy", "cost", "95% CI", "seeds", "seed range", "fn", "fp", "inspections", "violations"]
    for (sc, mode), g in T.groupby(["scenario", "mode"], sort=False):
        g = g.sort_values("cost"); g = g.assign(**{"95% CI": [f"[{f(a, 0)}, {f(b, 0)}]" for a, b in zip(g.lo, g.hi)], "seed range": [f"{f(a, 0)}–{f(b, 0)}" if s > 1 else "–" for a, b, s in zip(g.seed_min, g.seed_max, g.seeds)]})
        L += [f"## Scenario `{sc}` ({mode})", "", "Mean cost per episode (lower is better); 95% CI = bootstrap over evaluation episodes (learners: episode cost averaged over agent seeds).", "",
              md(g, cols, {"cost": lambda x: f(x, 0), "fn": lambda x: f(x, 1), "fp": lambda x: f(x, 1), "inspections": lambda x: f(x, 1), "violations": lambda x: f(x, 2), "seeds": str}), ""]
    L += ["## Paired comparison: learners vs the best non-learning baseline in each scenario", "",
          "The comparison baseline is chosen *by its evaluation cost* (the strongest baseline in hindsight), which is deliberately conservative against the learners. Difference = learner − baseline per episode (negative = learner cheaper); CI = bootstrap over episodes.", "",
          md(P.assign(**{"diff [95% CI]": [f"{f(m, 1)} [{f(a, 1)}, {f(b, 1)}]" for m, a, b in zip(P.mean_diff, P.lo, P.hi)]}), ["scenario", "mode", "learner", "best_nonlearning_baseline", "diff [95% CI]", "learner_better", "learner_worse"]), "",
          "## Summary counts (computed)", ""]
    for lname in ["RL_Q(full,g=0.97)", "RL_Q(budget_only,g=0.97)", "bandit(full,g=0)"]:
        q = P[P.learner == lname]
        if len(q): L.append(f"- `{lname}`: significantly cheaper than the best baseline in {int(q.learner_better.sum())} of {len(q)} scenario×mode cells, significantly more expensive in {int(q.learner_worse.sum())}, not distinguishable in {len(q) - int(q.learner_better.sum()) - int(q.learner_worse.sum())} (95% bootstrap CI over episodes).")
    L += ["", "Learning curves: `results/figures/rl_learning_curves.png`. Raw episode-level results: `results/rl_episode_results.csv`; training curves: `results/rl_training_curves.csv`. Mismatch rows (`mode` starting with `mismatch`) train on a stationary no-delay environment and evaluate on a bursty delayed noisy one, testing robustness to environment misspecification.", "",
          "Caveats: (i) one classifier's probabilities and one cost matrix drive the main table — see `results/rl_sensitivity_summary.csv` / the sensitivity section below if present; (ii) the learners were tuned only on development episodes drawn from the policy partition (see `results/rl_dev_tuning_round*.csv`), the baselines were hand-built and only the uncertainty band was tuned; (iii) a negative result for RL is a valid outcome of RQ2 and is reported as obtained."]
    sp = R / "rl_sensitivity_summary.csv"
    if sp.exists():
        S = pd.read_csv(sp); L += ["", "## Sensitivity to cost matrix and capacity (scenario bursty_d10_n0.1)", "", "Mean cost per episode; each block re-trains the learners under its own cost matrix/capacity (cost units differ between rows; compare within a row).", "", md(S, list(S.columns), {c: (lambda x: f(x, 0)) for c in S.columns if S[c].dtype.kind == "f"}), ""]
    (REP / "sequential_rl_results.md").write_text("\n".join(L) + "\n")
    return T, P, info

# ------------------------------------------------------------------ protocol + limitations
def protocol_report():
    sr = read_json(need("results/split_report.json")); A = read_json(need("results/dataset_audit.json"))
    c = cfg
    L = ["# Experimental protocol", "", "_Generated by `scripts/make_reports.py`; configuration values are read from `config/config.yaml`._", "",
         "## Data", "", f"Primary pool: `{c['data']['files']['master']}` (URL-level, labels 1=phishing / 0=legitimate; sources PhiUSIIL + Mendeley-450K). Rows after exclusions (empty host, label-conflicting normalised keys, normalised duplicates): {sr['pool_exclusions']['pool_rows']:,} of {sr['pool_exclusions']['input_rows']:,}. External set: `{c['data']['files']['recent']}` ({sr['recent_exclusions']['pool_rows']:,} rows after de-duplication), used **only for evaluation** and never for fitting classifiers, calibrators or thresholds. UCI benchmark is not used (no raw URLs; the supplied README forbids merging it). Tranco is not in the ZIP and not used. The raw files are read-only and hash-recorded (`results/dataset_audit.json`).", "",
         "## Splits (4 partitions)", "", "`train` (fit transformations and classifiers) · `val` (calibration, thresholds, calibrator choice, model selection) · `policy` (training streams for the contextual bandit/RL and tuning of the uncertainty band; never used to fit classifiers) · `test` (untouched until the protocol was fixed; reported). Fractions 0.60/0.10/0.10/0.20, assigned by a seeded SHA-256 hash of the group key so assignment is deterministic and order-independent.", "",
         "| protocol | grouping key | purpose |", "|---|---|---|", "| `random` (seed 42) | none (stratified rows) | reference baseline only — NOT an unseen-domain evaluation |", "| `hostname` (seed 42) | full hostname | hostname-disjoint |", f"| `regdomain` (seeds {c['seeds']}) | registered domain (eTLD+1, ICANN section of the Public Suffix List snapshot in `config/`) | **primary** leakage-resistant protocol |", "| `source_A_to_B` | train on one source, test on the other (registered domains of the test source removed from training) | cross-source shift |", "| chronological | — | **Not supported**: no timestamps in any supplied file |", "",
         "Every split is verified (`scripts/prepare_data.py`): URL / hostname / registered-domain overlap between every partition pair is computed and the run aborts if a protocol leaks at its own level. Counts and SHA-256 checksums are in `reports/split_report.md` and `results/split_report.json`.", "",
         "## Features and shortcut control", "", "Lexical features (`src/features/lexical.py`) and character 2–4-gram TF-IDF (fit on training rows only). The audit found `www.` present in ~99.9% of legitimate but ~28% of phishing URLs in the pooled data (collection artefact). Every model is therefore trained in two variants: **norm** (leading `www.` removed before featurisation; pre-declared primary) and **full** (URLs as supplied). No external lookups, WHOIS, page content or reputation data are used; nothing makes network requests.", "",
         "## Models", "", "Logistic regression on scaled lexical features (`lr_lex`), Random Forest (`rf_lex`), gradient boosting (`hgb_lex`: scikit-learn HistGradientBoosting — **XGBoost could not be installed offline**, so this is the documented substitute), char-TF-IDF + logistic regression (`tfidf_lr`), hybrid TF-IDF + lexical (`hybrid_lr`), and a stacked ensemble (`stack`: logistic meta-model over `lr_lex`, `hgb_lex`, `tfidf_lr` trained on **out-of-fold, group-aware** predictions). Tree models are fitted on a stratified subsample of the training rows (cap in config) for compute reasons. Hyper-parameters are fixed a priori (no grid search) — a documented limitation: no per-model tuning was performed.", "",
         "## Calibration, thresholds, uncertainty", "", "Calibrator ∈ {none, Platt, isotonic} is chosen per model by 2-fold group cross-fitting of the Brier score on the validation partition, then refit on all validation data. Thresholds (F1-optimal, cost-optimal) come from validation only. ECE uses 15 equal-width bins; reliability diagrams use 10. Confidence intervals: cluster bootstrap resampling registered domains (100 resamples by default, percentile 95%) for the primary split; seed variability over three registered-domain split seeds.", "",
         "## Decision layer and costs", "", f"Costs are assumptions: FN={c['cost']['fn']}, FP={c['cost']['fp']}, INSPECT={c['cost']['inspect']}; capacity {c['cost']['capacity_frac']:.0%} of arrivals. See `reports/cost_sensitive_results.md`.", "",
         "## Sequential RL", "", f"Configuration: {json.dumps(c['rl'])}. See `reports/sequential_rl_results.md` for the environment definition.", "",
         "## Shift and adaptation", "", "Observed shifts (held-out registered domains, cross-source, external set) are kept separate from simulated shifts (prevalence, covariate perturbation, evasion padding, input-preserving concept drift). Adaptation is an offline simulation. See the respective reports.", "",
         "## Reproduction", "", "`python scripts/run_all.py` (see README). Dataset SHA-256 and config hash are recorded in `results/run_status.json` and in every prediction metadata file."]
    (REP / "experimental_protocol.md").write_text("\n".join(L) + "\n")

def limitations_report():
    L = ["# Limitations and threats to validity", "",
         "_Static text written by the authors; numeric claims live in the generated reports._", "",
         "1. **No timestamps.** No supplied file has a per-row date; the 'recent' set has dataset-level provenance only. Temporal generalisation is **not supported by the data** and is never claimed; the external set is analysed as an external-source, mostly domain-novel holdout. Its class construction differs from the pooled data (different URL length/path/`www.` profiles per class), so a performance drop there mixes real shift with dataset-construction artefacts.",
         "2. **Label provenance and shortcuts.** Labels come from aggregated public sources; class-specific collection pipelines create trivially computable shortcuts (`www.`, length). We mitigate (variant `norm`) but cannot prove all shortcuts are removed. Absolute accuracy numbers should not be read as deployable accuracy; relative comparisons between protocols are the more reliable output.",
         "3. **Domain-disjointness is relative to the PSL ICANN section.** Private-suffix hosts (e.g. hosting platforms) are grouped under the provider, which is conservative; look-alike and typo-squat domains of the same brand remain in different groups and can still leak semantically.",
         "4. **No XGBoost / deep models.** The environment had no package-index access. HistGradientBoosting substitutes for XGBoost; no neural URL models (e.g. character CNNs) were trained. No per-model hyper-parameter search was run; tree models use a training subsample. Conclusions about model ranking are conditional on these choices.",
         "5. **Assumed costs.** The cost matrix, inspection price, capacity, delay and noise distributions are assumptions; no operational data was available. Conclusions about policies hold for the tested assumptions (plus the sensitivity grid where reported), not for real operations.",
         "6. **RL is simulated and tabular.** Transitions are an authored model of an inspection queue, not observations. The agent is tabular Q-learning on a coarse discretisation; function-approximation or deep RL, policy-gradient methods, and better exploration were not explored, so a negative or mixed RL result does not rule out better RL designs. Learners are compared with hand-built heuristics that were designed with knowledge of the environment's structure.",
         "7. **Monitoring limits.** Input-only detectors (PSI/KS) cannot detect concept drift with unchanged inputs; the shift experiment demonstrates this by construction. PSI > 0.25 is a rule of thumb, not a validated threshold.",
         "8. **Adaptation is an offline simulation.** Feedback, analyst noise and poisoning are simulated with a non-adaptive attacker; gates are hand-set. No claim of robustness to adaptive adversaries or of production readiness is made.",
         "9. **Statistics.** Bootstrap CIs resample registered domains (supervised) or evaluation episodes (RL) and ignore other variance sources (training randomness, split choice) except where seeds are explicitly varied; no formal significance tests or multiple-comparison corrections are applied.",
         "10. **Novelty.** The literature search was limited (see `reports/literature_review.md`); no claim of novelty is made.",
         "11. **Not production-ready.** The prediction CLI is an offline research prototype (URL string only). No security review, production testing or latency under load was performed; latency numbers are single-process CPU indications on a 2-core container."]
    (REP / "limitations.md").write_text("\n".join(L) + "\n")

# ------------------------------------------------------------------ final report
def final_report(T, P, rlinfo):
    sr = read_json(need("results/split_report.json")); A = read_json(need("results/dataset_audit.json"))
    M = pd.read_csv(need("results/supervised_metrics.csv")); CI = pd.read_csv(need("results/supervised_bootstrap_ci.csv")); SYS = pd.read_csv(need("results/system_costs.csv"))
    SH = pd.read_csv(need("results/shift_results.csv")); AD = pd.read_csv(need("results/adaptation_summary.csv")); ST = read_json(need("results/run_status.json"))
    prim = f"regdomain_seed{cfg['seeds'][0]}"; asel = lambda **k: M.query(" and ".join(f"{a} == {v!r}" for a, v in k.items()))
    L = ["# Final research report", "", "_Assembled by `scripts/make_reports.py` from saved outputs; every number below is read from `results/`. Narrative interpretation (section 14) is hand-written after inspecting these tables._", "",
         f"Run mode of the pipeline stages: {ST['mode']}; stage exit statuses: " + ", ".join(f"{s['stage']}={s['exit_status']}" for s in ST["stages"]) + f". Master dataset SHA-256 `{ST['dataset_master_sha256'][:16]}…`; config SHA-256 `{ST['config_sha256'][:16]}…`.", "",
         "## Result status legend", "", "| component | status |", "|---|---|", "| Dataset audit, splits, leakage checks | Executed and verified |", "| Supervised baselines, calibration, CIs | Executed and verified |", "| Cost-sensitive static policies | Executed and verified (assumed costs) |",
         f"| Sequential RL environment and comparison | Simulated ({'FAST reduced budget — partially executed' if rlinfo.get('fast') else 'full configured budget'}) |", "| Distribution shift (held-out domains, cross-source, external set) | Executed and verified (observed shifts); simulated shifts labelled `sim:` |", "| Safe adaptation | Simulated |", "| Chronological / temporal evaluation | Not supported by the available data |", "| XGBoost, deep neural URL models | Not executed (no package access) |", "",
         "## 1. Research problem and motivation", "", "Phishing-URL detectors are usually reported with random-split accuracy near 99%, but deployment faces unseen domains, shifting prevalence, limited analyst capacity and delayed noisy feedback. This project builds a leakage-resistant evaluation, a cost-aware ALLOW/BLOCK/INSPECT layer, a *sequential* inspection environment in which actions change later options, and a gated adaptation mechanism, and asks whether each layer measurably helps.", "",
         "## 2. Research questions and evidence-supported gaps", "", "RQ1 generalisation under domain-disjoint evaluation and shift; RQ2 sequential RL vs supervised / cost-sensitive / bandit baselines under capacity, delay and noise; RQ3 safe feedback-gated adaptation. Full text: `reports/research_questions.md`. Gap-by-gap literature status (no novelty claimed): `reports/research_gap_analysis.md`; review and verification levels: `reports/literature_review.md`; bibliography `references.bib`.", ""]
    s = A["splits"]; mc = A["master"] if "master" in A else {}
    L += ["## 3. Dataset description and provenance", "", f"Supplied archive SHA-256 `{cfg['data']['expected_zip_sha256']}`. Supplied URL splits (rows / % phishing): " + "; ".join(f"{k} {v['rows']:,} / {v['phish_pct']}%" for k, v in s.items()) + ". The supplied train/val/test split is hostname-disjoint but **not registered-domain-disjoint** (sibling subdomains cross splits); `domain` is the full hostname. No timestamps. Detailed audit: `reports/dataset_audit.md`.", "",
         "## 4. Leakage and evaluation protocol", "", f"Pool after exclusions: {sr['pool_exclusions']['pool_rows']:,} URLs. Distinct registered domains shared between train and test under each protocol (seed-42 / first seed):", "", "| protocol | URL overlap | hostname overlap | registered-domain overlap | verified disjoint at own level |", "|---|---:|---:|---:|---|"]
    for pn in ["random_seed42", "hostname_seed42", prim]:
        v = sr["protocols"][pn]; o = v["overlap"]["train~test"]; L.append(f"| {pn} | {o['url']:,} | {o['hostname']:,} | {o['regdomain']:,} | {v['disjoint_at_level']} |")
    L += ["", "Full protocol: `reports/experimental_protocol.md`; split details `reports/split_report.md`.", "",
          "## 5–6. Methods, baselines and fairness", "", "See `reports/experimental_protocol.md`. All models share the same partitions, features, calibration procedure and metrics; transformations are fitted on training rows only; the stack uses out-of-fold group-aware predictions; learners and baselines in the RL comparison share the same observation tuple, budget, action masking and cost model; evaluation episodes are pre-drawn and identical for every policy.", "",
          "## 7. Supervised results (RQ1)", ""]
    # RQ1 table: ROC-AUC/F1 by protocol, norm variant
    t = asel(eval_set="test", calibration="cal", thr_name="val_f1", variant="norm")
    t = t[t.protocol.isin(["random_seed42", "hostname_seed42", prim])]
    pv = t.pivot_table(index="kind", columns="protocol", values="pr_auc"); pf = t.pivot_table(index="kind", columns="protocol", values="f1")
    L += [f"Test PR-AUC and F1 by evaluation protocol, variant `norm`, calibrated, F1-optimal validation threshold (PR-AUC | F1):", "", "| model | random | hostname | registered-domain |", "|---|---|---|---|"]
    for k in pv.index: L.append(f"| {k} | " + " | ".join(f"{f(pv.loc[k, p], 4)} \\| {f(pf.loc[k, p], 4)}" if p in pv.columns else "n/a" for p in ["random_seed42", "hostname_seed42", prim]) + " |")
    d = (pv["random_seed42"] - pv[prim]); L += ["", f"Computed: mean PR-AUC drop from random split to registered-domain-disjoint split across models = {d.mean():.4f} (min {d.min():.4f}, max {d.max():.4f}). Note this protocol difference also changes the partition sizes/composition, and the random split shares {sr['protocols']['random_seed42']['overlap']['train~test']['regdomain']:,} registered domains between train and test.", ""]
    for variant in ["norm", "full"]:
        q = asel(protocol=prim, variant=variant, eval_set="test", calibration="cal", thr_name="val_f1")
        if len(q): L += [f"### Primary protocol `{prim}`, variant `{variant}` (test, calibrated, val-F1 threshold)", "", md(q.sort_values("kind"), ["kind", "accuracy", "precision", "recall", "f1", "roc_auc", "pr_auc", "fp", "fn", "brier", "ece"], {"fp": str, "fn": str}), ""]
    q = asel(protocol=prim, variant="norm", thr_name="fixed_0.5", eval_set="test"); rows = []
    for k, g in q.groupby("kind"):
        r, c = g[g.calibration == "raw"].iloc[0], g[g.calibration == "cal"].iloc[0]; rows.append(dict(model=k, calibrator=r.calibrator, brier_raw=r.brier, brier_cal=c.brier, ece_raw=r.ece, ece_cal=c.ece))
    L += ["### Calibration before/after (primary, norm, test)", "", md(pd.DataFrame(rows), ["model", "calibrator", "brier_raw", "brier_cal", "ece_raw", "ece_cal"], {c: (lambda x: f(x, 4)) for c in ["brier_raw", "brier_cal", "ece_raw", "ece_cal"]}), ""]
    rec = asel(protocol=prim, variant="norm", eval_set="recent_all", calibration="cal", thr_name="val_f1")
    L += ["### External 'recent' set (not temporal evidence), primary norm models", "", md(rec.sort_values("kind"), ["kind", "roc_auc", "pr_auc", "f1", "precision", "recall", "ece"]), "",
          "Complete tables (all protocols, variants, thresholds, raw vs calibrated): `reports/supervised_results.md`, `results/supervised_metrics.csv`.", "",
          "## 8. Statistical uncertainty", "", "Group-bootstrap 95% CIs over registered domains (primary split) and mean ± sd over split seeds are in `reports/supervised_results.md` and `results/supervised_bootstrap_ci.csv`. Seed-level spread (norm, calibrated, test PR-AUC):", ""]
    sd = asel(eval_set="test", calibration="cal", thr_name="val_f1", variant="norm"); sd = sd[sd.protocol.str.startswith("regdomain_seed")]
    g = sd.groupby("kind").pr_auc.agg(["count", "mean", "std"]).reset_index(); L += [md(g, ["kind", "count", "mean", "std"], {"count": str, "mean": lambda x: f(x, 4), "std": lambda x: f(x, 4)}), ""]
    L += ["## 9. Cost-sensitive policies", "", "Static comparison in `reports/cost_sensitive_results.md` (assumed costs). Cheapest policies per classifier block, computed:", ""]
    C = pd.read_csv(R / "cost_static_policies.csv")
    for cl, gg in C.groupby("classifier", sort=False):
        gg = gg.sort_values("cost"); online = gg[~gg.policy.str.contains("batch_topK|unconstrained")]
        L.append(f"- {cl}: cheapest online policy under the capacity limit = `{online.iloc[0].policy}` ({online.iloc[0].cost_per_1k:.1f} per 1k); `fixed_0.5` = {gg[gg.policy == 'fixed_0.5'].cost_per_1k.iloc[0]:.1f} per 1k.")
    L += ["", "## 10. Sequential RL vs non-RL baselines (RQ2) — SIMULATED", ""]
    for lname in ["RL_Q(full,g=0.97)", "RL_Q(budget_only,g=0.97)", "bandit(full,g=0)"]:
        q = P[P.learner == lname]
        if len(q): L.append(f"- `{lname}`: cheaper than the best non-learning baseline (hindsight-selected) in {int(q.learner_better.sum())}/{len(q)} cells, more expensive in {int(q.learner_worse.sum())}/{len(q)}, indistinguishable in {len(q) - int(q.learner_better.sum()) - int(q.learner_worse.sum())}/{len(q)}.")
    best = T[T["mode"] == "matched"].sort_values("cost").groupby("scenario").head(3)
    L += ["", "Three cheapest policies per matched scenario (mean cost/episode):", "", md(best[["scenario", "policy", "cost", "lo", "hi"]], ["scenario", "policy", "cost", "lo", "hi"], {"cost": lambda x: f(x, 0), "lo": lambda x: f(x, 0), "hi": lambda x: f(x, 0)}), "", "Full tables with seeds, FN/FP, inspections and paired differences: `reports/sequential_rl_results.md`.", "",
          "## 11. Distribution shift (RQ1) and safe adaptation (RQ3)", "", "Shift table (key columns; `observed` = real held-out data, `sim:*` = synthetic perturbation):", ""]
    L += [md(SH[["name", "kind", "n", "roc_auc", "pr_auc", "ece", "cost_per_1k", "score_psi", "max_feature_psi", "input_drift_alert", "label_alert"]], ["name", "kind", "n", "roc_auc", "pr_auc", "ece", "cost_per_1k", "score_psi", "max_feature_psi", "input_drift_alert", "label_alert"], {"n": str}), "", "Full text: `reports/distribution_shift_results.md`.", "",
          "Adaptation (final held-out cost per 1k, mean over seeds; lower is better):", ""]
    g = AD.groupby(["scenario", "poison", "strategy"]).agg(cost=("final_eval_cost_per_1k", "mean"), auc=("final_eval_auc", "mean"), acc=("accepted", "mean"), rej=("rejected", "mean"), rb=("rollbacks", "mean")).reset_index()
    L += [md(g, ["scenario", "poison", "strategy", "cost", "auc", "acc", "rej", "rb"], {"cost": lambda x: f(x, 1), "auc": lambda x: f(x, 4), "acc": lambda x: f(x, 1), "rej": lambda x: f(x, 1), "rb": lambda x: f(x, 1)}), "", "Full text and threat model: `reports/safe_adaptation_results.md`.", "",
          "## 12. Computational and operational considerations", "", "Primary-split models (CPU, 2 cores, single process; indicative only):", "", md(SYS[SYS.protocol == prim].sort_values(["variant", "kind"]), ["variant", "kind", "fit_seconds", "latency_ms", "model_MB", "calibrator"], {"fit_seconds": lambda x: f(x, 1), "latency_ms": lambda x: f(x, 3), "model_MB": lambda x: f(x, 2)}), "",
          "Offline prediction CLI: `python scripts/predict_url.py <url>` (no network access; URL string only; prototype, not production-validated).", "",
          "## 13. Limitations, threats to validity, future work", "", "See `reports/limitations.md`. Future work that the data/environment did not allow: timestamped data for temporal evaluation; XGBoost and neural URL models with proper tuning; operational cost and feedback-delay data to ground the simulator; function-approximation RL; adaptive-adversary evaluation.", "",
          "## 14. Interpretation (author's reading)", ""]
    ip = REP / "interpretation.md"
    L += [ip.read_text() if ip.exists() else "_reports/interpretation.md is missing._", "",
          "## 15. Reproduction commands and artifact locations", "", "```\npip install -r requirements.txt\npython scripts/run_all.py          # all stages; logs in logs/, status in results/run_status.json\npython -m unittest discover -s tests\npython scripts/predict_url.py http://example.com\n```", "", "Artifacts: `results/` (CSV/JSON/figures/predictions), `artifacts/models` (primary-split models), `artifacts/deployable_bundle.joblib`, `reports/`, `MANIFEST.json` (file hashes)."]
    (REP / "final_research_report.md").write_text("\n".join(L) + "\n")

def main():
    cost_report(); T, P, info = rl_report(); protocol_report(); limitations_report()
    for p in ["reports/dataset_audit.md", "reports/supervised_results.md", "reports/distribution_shift_results.md", "reports/safe_adaptation_results.md", "reports/literature_review.md", "reports/research_gap_analysis.md", "reports/research_questions.md"]: need(p)
    final_report(T, P, info); print("reports written")

if __name__ == "__main__": main()
